Translate("ptBR", "gnomeregan", {
	title = "Gnomeregan",
	aliases = { "cidade de Gnomeregan" },
	sections = {
		{
			title = "Resumo",
			text = [=[Gnomeregan era a cidade dos {link:gnomes}gnomos{/link}, uma maravilha do mundo construída nas colinas ocidentais de {link:dun-morogh}Dun Morogh{/link}. Seus salões estavam cheios de grandes engenhos, servos mecânicos e aparelhos que nenhum outro povo poderia ter sonhado. Hoje é uma ruína envenenada. Seus portões são vigiados pelos sobreviventes doentes e enlouquecidos de sua queda, suas profundezas fervilham de {link:troggs}troggs{/link} e de lodo vivo, e em seu coração está o gnomo que a traiu.]=],
		},
		{
			title = "Origens",
			text = [=[Os gnomos construíram Gnomeregan com as próprias mãos, como vizinhos e amigos dos {link:dwarves}anões{/link} de {link:ironforge}Altaforja{/link}. Nenhuma crônica registra o ano de sua fundação. Por gerações ela foi a sede do Grão-Engenhoqueiro e o orgulho do povo {link:gnomes}gnomo{/link}, e de suas oficinas saíram muitas das máquinas que serviram à {link:alliance}Aliança{/link} na {link:second-war}Segunda Guerra{/link}.]=],
		},
		{
			title = "A Queda",
			text = [=[Os troggs subiram das profundezas sob a cidade em números que os gnomos não conseguiram conter. O Grão-Engenhoqueiro {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} decidiu expurgá-los com uma arma de fabricação dos próprios gnomos. Ela matou troggs, mas matou também um grande número de gnomos, e deixou a cidade encharcada de veneno. Muitos dos que sobreviveram se tornaram leprosos, doentes no corpo e vazios na mente. Os demais fugiram para {link:ironforge}Altaforja{/link}. Atrás deles, o {link:mekgineer-thermaplugg}Mecagenheiro Thermaplugg{/link}, em quem o Grão-Engenhoqueiro havia confiado, tomou a cidade para si.]=],
		},
		{
			title = "Dentro das Muralhas",
			text = [=[• {b}A entrada.{/b} Uma {link:gnomes}gnomo{/link} chamada Emi Shortfuse defende os portões contra os troggs com explosivos e pouquíssima paciência.
• {b}A Zona Limpa.{/b} Um bando de resistentes gnomos se agarra a uma sala livre de veneno, onde uma estranha máquina chamada Sparklematic 5200 ainda esfrega e embrulha tudo o que lhe dão.
• {b}As profundezas.{/b} Lodos envenenados, máquinas quebradas e um robô rebelde chamado Techbot vagam pelos salões inferiores. Um dia ele foi ajudante dos engenhoqueiros. Uma faísca inverteu sua mente.
• {b}Os senhores.{/b} {link:grubbis}Grubbis{/link} lidera os troggs da cidade. {link:mekgineer-thermaplugg}Thermaplugg{/link} comanda os gnomos leprosos e as máquinas. {link:dark-iron-dwarves}Anões Ferro Negro{/link} andam livremente entre eles, e um enviado Ferro Negro às vezes é encontrado nos salões.]=],
		},
		{
			title = "Chefes",
			text = [=[• {b}{link:grubbis}Grubbis{/link}{/b}, chefe dos troggs de Gnomeregan.
• {b}{link:viscous-fallout}Viscous Fallout{/link}{/b}, uma massa viva do veneno da cidade.
• {b}{link:electrocutioner-6000}Electrocutioner 6000{/link}{/b}, uma máquina de guerra que ainda guarda seu posto.
• {b}{link:crowd-pummeler-9-60}Crowd Pummeler 9-60{/link}{/b}, um brutamontes mecânico enorme.
• {b}{link:dark-iron-ambassador}Embaixador Ferro Negro{/link}{/b}, um enviado dos {link:dark-iron-dwarves}Ferro Negro{/link} que nem sempre está presente.
• {b}{link:mekgineer-thermaplugg}Mecagenheiro Thermaplugg{/link}{/b}, o traidor que governa as ruínas.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Os {link:gnomeregan-exiles}exilados de Gnomeregan{/link} não esqueceram sua cidade. De {link:tinker-town}Tinker Town{/link} eles enviam voluntários de volta por seus portões para resgatar registros perdidos, recuperar peças e salvar as máquinas que deixaram para trás. Em {link:kharanos}Kharanos{/link}, dois gnomos coletam o veneno da cidade na esperança de uma cura. E os goblins da {link:horde}Horda{/link} descobriram que {link:mekgineer-thermaplugg}Thermaplugg{/link} está construindo uma grande máquina, uma engenhoca melhor que qualquer uma das deles, e querem seus projetos.]=],
		},
	},
})

