		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "o Grão-Engenhoqueiro que ele traiu" },
		{ id = "grubbis", name = "Grubbis", note = "lidera os troggs de sua cidade" },
		{ id = "dark-iron-ambassador", name = "Embaixador Ferro Negro", note = "um enviado de seus aliados" },
	},
})

Translate("ptBR", "grubbis", {
