			text = [=[Grubbis é o rosto da invasão {link:troggs}trogg{/link} que destruiu {link:gnomeregan}Gnomeregan{/link}. O expurgo dos gnomos não aniquilou seu povo; apenas o tornou mais estranho.]=],
		},
