Translate("ptBR", "viscous-fallout", {
	title = "Viscous Fallout",
	subtitle = "O Veneno Vivo",
	found = "As profundezas envenenadas de Gnomeregan",
	allegiance = "Nenhuma",
	sections = {
		{
			title = "Resumo",
			text = [=[Viscous Fallout é o que o expurgo de {link:gnomeregan}Gnomeregan{/link} deixou para trás. É uma massa ondulante de lodo verde, nascida do veneno que inundou a cidade, e espreita nas profundezas onde o veneno corre mais espesso. Lodos e horrores menores rastejam à sua volta. Os gnomos que estudam o veneno em {link:kharanos}Kharanos{/link} querem amostras de tais criaturas, colhidas frescas, pois dizem que os resíduos dos troggs são fracos demais para seu trabalho.]=],
		},
		{
			title = "Importância",
			text = [=[Viscous Fallout é a própria arma dos gnomos transformada em corpo. É o único inimigo em {link:gnomeregan}Gnomeregan{/link} pelo qual ninguém mais pode ser culpado.]=],
		},
	},
})

Translate("ptBR", "electrocutioner-6000", {
