	subtitle = "Máquina Guardiã de Gnomeregan",
	found = "Os salões de Gnomeregan",
	allegiance = "Máquinas de Gnomeregan",
	sections = {
		{
			title = "Resumo",
			text = [=[Electrocutioner 6000 é uma grande máquina de guerra de {link:gnomeregan}Gnomeregan{/link}, armada com relâmpagos. Foi construída para guardar a cidade. Seus criadores se foram, ou foram envenenados, ou estão no exílio, mas a máquina continua em seu posto e abate qualquer um que se aproxime.]=],
		},
		{
			title = "Importância",
			text = [=[O Electrocutioner mostra o lado amargo do gênio gnômico. As defesas da cidade foram bem-feitas demais, e agora a defendem contra o próprio povo.]=],
		},
	},
})

Translate("ptBR", "crowd-pummeler-9-60", {
	title = "Crowd Pummeler 9-60",
	subtitle = "Brutamontes Mecânico",
	found = "Um grande salão de Gnomeregan",
	allegiance = "Máquinas de Gnomeregan",
	sections = {
		{
			title = "Resumo",
			text = [=[Crowd Pummeler 9-60 é uma máquina enorme de {link:gnomeregan}Gnomeregan{/link}, construída, como seu nome alardeia, para espancar multidões. Ainda pisoteia e golpeia num dos grandes salões da cidade, como se seus criadores estivessem assistindo. Se os gnomos a construíram por esporte, para a guerra ou para manter a ordem em suas ruas, nenhum sobrevivente se deu ao trabalho de dizer.]=],
		},
		{
			title = "Importância",
