		},
	},
})

Translate("ptBR", "dark-iron-ambassador", {
	title = "Embaixador Ferro Negro",
	subtitle = "Enviado dos Ferro Negro",
	found = "Os salões de Gnomeregan (nem sempre presente)",
	allegiance = "Anões Ferro Negro",
	sections = {
		{
			title = "Resumo",
			text = [=[O Embaixador Ferro Negro é um enviado dos {link:dark-iron-dwarves}Ferro Negro{/link}, encontrado às vezes nos salões de {link:gnomeregan}Gnomeregan{/link}, guardado pelo fogo. Que negócios os Ferro Negro têm com {link:mekgineer-thermaplugg}Thermaplugg{/link} não está escrito em lugar algum. Ainda assim, os sinais são muitos: um {link:gnomes}gnomo{/link} cativo espancado por anões Ferro Negro, o anel de um joalheiro gnomo encontrado no cadáver de um Ferro Negro, e uma nova engenhoca construída com a ajuda dos Ferro Negro.]=],
		},
		{
			title = "Importância",
			text = [=[O Embaixador é a prova de que a ruína de {link:gnomeregan}Gnomeregan{/link} faz parte de uma teia maior, e de que o velho inimigo de {link:ironforge}Altaforja{/link} também estendeu a mão até a cidade dos gnomos.]=],
		},
	},
})
